void need(bool ok,const char* why){if(!ok)throw std::runtime_error(std::string("BRep pair: ")+why);}
void fields(const Json& j,std::set<std::string> keys){need(j.is_object()&&j.size()==keys.size(),"unsupported fields");for(auto it=j.begin();it!=j.end();++it)need(keys.count(it.key())!=0,"unsupported field");}
double num(const Json& j,double cap=1e30,bool positive=false){need(j.is_number(),"numeric field");double v=j.get<double>();need(std::isfinite(v)&&std::abs(v)<=cap&&(!positive||v>=0),"numeric domain");return v;}
std::size_t count(const Json& j,std::size_t cap){need(j.is_number_integer()&&num(j,double(cap),true)<=double(cap),"count domain");return j.get<std::size_t>();}
void flag(const Json& j){need(j.is_boolean(),"boolean field");}
void text(const Json& j,std::size_t cap=4096){need(j.is_string()&&j.get<std::string>().size()<=cap,"text budget");}
QByteArray bytes(const QString& p,bool allowEmpty=false){QFile f(p);need(f.open(QIODevice::ReadOnly)&&(allowEmpty||f.size()>0)&&f.size()<=16*1024*1024,"file byte budget");auto b=f.read(16*1024*1024+1);need(f.error()==QFileDevice::NoError&&b.size()<=16*1024*1024,"file read");return b;}
Json parse(const QByteArray& b){std::vector<std::set<std::string>> keys;return Json::parse(b.toStdString(),[&](int depth,Json::parse_event_t e,Json& v){need(depth<=32,"JSON depth budget");if(e==Json::parse_event_t::object_start)keys.emplace_back();else if(e==Json::parse_event_t::key)need(keys.back().insert(v.get<std::string>()).second,"duplicate JSON key");else if(e==Json::parse_event_t::object_end)keys.pop_back();return true;});}
void digest(const Json& j){text(j,64);need(QRegularExpression("^[0-9a-f]{64}$").match(QString::fromStdString(j)).hasMatch(),"SHA format");}
void identity(const Json& j){fields(j,{"file_name","size_bytes","sha256"});text(j.at("file_name"),256);need(count(j.at("size_bytes"),1024ULL*1024*1024)>0,"identity size");digest(j.at("sha256"));}
void topology(const Json& p,bool source){
    auto names=std::set<std::string>{"solid_count","shell_count","face_count","edge_count","vertex_count","topology_valid","all_shells_closed","infinite_point_states"};
    if(source)for(const char* n:{"boolean_arguments_valid","argument_errors","argument_warnings","bounds_xyzxyz_mm","default_volume_mm3","surface_area_mm2","max_entity_tolerance_mm","brep_sha256"})names.insert(n);else names.insert("integrals");fields(p,names);
    for(const char* n:{"solid_count","shell_count","face_count","edge_count","vertex_count"})count(p.at(n),20000);flag(p.at("topology_valid"));flag(p.at("all_shells_closed"));need(p.at("infinite_point_states").is_array()&&p.at("infinite_point_states").size()==p.at("solid_count"),"infinite point count");for(const auto& s:p.at("infinite_point_states"))need(s=="OUT"||s=="NOT_OUT","infinite point state");
    if(source){flag(p.at("boolean_arguments_valid"));text(p.at("argument_errors"));text(p.at("argument_warnings"));need(p.at("bounds_xyzxyz_mm").is_array()&&p.at("bounds_xyzxyz_mm").size()==6,"bounds shape");for(const auto& v:p.at("bounds_xyzxyz_mm"))num(v,1e9);for(int k=0;k<3;++k)need(p.at("bounds_xyzxyz_mm")[k].get<double>()<=p.at("bounds_xyzxyz_mm")[k+3].get<double>(),"bounds order");num(p.at("default_volume_mm3"));num(p.at("surface_area_mm2"),1e30,true);num(p.at("max_entity_tolerance_mm"),1e9,true);digest(p.at("brep_sha256"));}
    else{const auto& a=p.at("integrals");need(a.is_array()&&a.size()==(p.at("solid_count")==0?0:4),"integral sequence size");for(std::size_t i=0;i<a.size();++i){const auto& r=a[i];fields(r,{"method","requested_eps","estimated_relative_error","volume_mm3"});need(r.at("method")==((i<2)?"gauss":"kronrod")&&r.at("requested_eps")==((i%2==0)?1e-9:1e-11),"integral method/eps");num(r.at("estimated_relative_error"));num(r.at("volume_mm3"));}}
}
bool qualified(const Json& p){return p.at("topology_valid")==true&&p.at("solid_count")==1&&p.at("shell_count").get<int>()>0&&p.at("all_shells_closed")==true&&p.at("infinite_point_states")==Json::array({"OUT"})&&p.at("boolean_arguments_valid")==true&&p.at("default_volume_mm3").get<double>()>0;}
double margin(const Json& a,const Json& b){return 10*std::max({1e-6,a.at("max_entity_tolerance_mm").get<double>(),b.at("max_entity_tolerance_mm").get<double>()});}
double gap(const Json& a,const Json& b){double g=0;for(int k=0;k<3;++k)g=std::max({g,a.at("bounds_xyzxyz_mm")[k].get<double>()-b.at("bounds_xyzxyz_mm")[k+3].get<double>(),b.at("bounds_xyzxyz_mm")[k].get<double>()-a.at("bounds_xyzxyz_mm")[k+3].get<double>()});return g;}
std::string assess(const Json& job,const Json& a,const Json& b){
    if(!qualified(a)||!qualified(b))return "unqualified_brep";
    if(job.at("job_status")!="completed"||job.at("inputs_unchanged")!=true)return "unresolved_job_failure";
    const auto& runs=job.at("runs");for(const auto& r:runs)if(r.at("operation_ok")!=true||r.at("inputs_unchanged")!=true)return "unresolved_boolean_failure";
    for(const auto& r:runs)if(r.at("has_warnings")==true)return "unresolved_boolean_warning";
    for(const auto& r:runs){const auto& s=r.at("common");if(s.at("topology_valid")!=true||s.at("all_shells_closed")!=true)return "unresolved_common_topology";for(const auto& state:s.at("infinite_point_states"))if(state!="OUT")return "unresolved_common_topology";}
    for(const auto& r:runs)for(const char* key:{"solid_count","face_count","edge_count","vertex_count"})if(r.at("common").at(key)!=runs[0].at("common").at(key))return "unresolved_order_or_fuzzy_topology";
    bool positive=true;for(const auto& r:runs)positive=positive&&r.at("common").at("solid_count").get<int>()>0;
    if(positive){const auto& ds=job.at("distances");double da=ds[0].at("solid_distance_mm"),db=ds[1].at("solid_distance_mm"),ba=ds[0].at("boundary_distance_mm"),bb=ds[1].at("boundary_distance_mm");if(std::abs(da-db)>1e-7||std::abs(ba-bb)>1e-7)return "unresolved_distance_order";if(std::max(da,db)>margin(a,b))return "unresolved_distance_common_inconsistent";double low=1e100,high=0;for(const auto& r:runs){double lo=1e100,hi=0;for(const auto& i:r.at("common").at("integrals")){double v=i.at("volume_mm3").get<double>(),err=i.at("estimated_relative_error").get<double>();if(v<=0||err<0||err>1e-8)return "unresolved_volume_integration";lo=std::min(lo,v);hi=std::max(hi,v);}if(hi/lo-1>1e-8)return "unresolved_volume_integration";low=std::min(low,lo);high=std::max(high,hi);}if(high/low-1>1e-7)return "unresolved_order_or_fuzzy_volume";return low>std::max(1e-12,margin(a,b)*std::max(a.at("surface_area_mm2").get<double>(),b.at("surface_area_mm2").get<double>()))?"numerical_common_solid_observed":"unresolved_below_volume_resolution";}
    for(const auto& r:runs)if(r.at("common").at("solid_count").get<int>()>0)return "unresolved_order_or_fuzzy_topology";
    const auto& d=job.at("distances");double x=d[0].at("solid_distance_mm"),y=d[1].at("solid_distance_mm"),p=d[0].at("boundary_distance_mm"),q=d[1].at("boundary_distance_mm");if(std::abs(x-y)>1e-7||std::abs(p-q)>1e-7)return "unresolved_distance_order";if(std::min(x,y)>margin(a,b))return "numerical_separation_observed";if(std::max(p,q)<=margin(a,b)&&d[0].at("inner_solution")==false&&d[1].at("inner_solution")==false)return "tolerance_near_or_contact_candidate";return "unresolved_distance_common_inconsistent";
}
