StepRelationReview inspectStepBrepPairsFile(const QString& manifestPath,const QString& receiptPath){
    auto out=inspectStepContactEvidenceFile(manifestPath);const auto& conversion=out.report.at("step_conversion");need(conversion.contains("assembly_audit")&&conversion.at("assembly_audit").at("qualified")==true,"qualified XDE package required");auto raw=bytes(receiptPath);auto a=parse(raw);
    fields(a,{"schema","policy","contact_review","backend","worker","bodies","pairs","classification_counts","numerical_scan_complete","pair_job_budget","pair_job_count","pair_timeout_seconds","requested_fuzzy_mm","actual_fuzzy_mm","integration_eps","integration_relative_tolerance","pair_volume_relative_tolerance","transport_allowed","source_fidelity_certified","provenance_authenticated","whole_pair_geometry_certified","scope","evidence_files"});
    need(a.at("schema")=="scdat.brep-pair-audit/1"&&a.at("policy")=="scdat.brep-whole-pair-numerical/1"&&a.at("contact_review")==out.report,"receipt/contact context mismatch");need(a.at("backend")==conversion.at("assembly_audit").at("tree").at("backend"),"backend mismatch");identity(a.at("worker"));for(const char* key:{"transport_allowed","source_fidelity_certified","provenance_authenticated","whole_pair_geometry_certified"})need(a.at(key)==false,"unsupported certification claim");text(a.at("scope"));
    need(a.at("pair_job_budget")==64&&a.at("pair_timeout_seconds")==60&&a.at("requested_fuzzy_mm")==Json::array({0.,1e-6})&&a.at("actual_fuzzy_mm")==Json::array({1e-7,1e-6})&&a.at("integration_eps")==Json::array({1e-9,1e-11})&&a.at("integration_relative_tolerance")==1e-8&&a.at("pair_volume_relative_tolerance")==1e-7,"unsupported numerical policy");
    QDir root(QFileInfo(receiptPath).absolutePath());std::map<std::string,Json> fileRecords;std::map<std::string,QByteArray> fileBytes;std::size_t total=0;need(a.at("evidence_files").is_array()&&a.at("evidence_files").size()<=512,"evidence count budget");
    for(const auto& f:a.at("evidence_files")){fields(f,{"path","file_name","size_bytes","sha256"});text(f.at("path"),256);auto name=f.at("path").get<std::string>();auto relative=QString::fromStdString(name);need(QRegularExpression("^[A-Za-z0-9_.-]+(/[A-Za-z0-9_.-]+){0,3}$").match(relative).hasMatch(),"unsafe evidence path");for(const auto& part:relative.split('/'))need(part!="."&&part!="..","evidence traversal");auto absolute=root.filePath(relative);QFileInfo info(absolute);QString current=root.absolutePath();for(const auto& component:relative.split('/')){current=QDir(current).filePath(component);need(!QFileInfo(current).isSymLink(),"symlink evidence");}need(info.canonicalFilePath().startsWith(root.canonicalPath()+"/",Qt::CaseInsensitive),"evidence outside root");auto b=bytes(absolute,true);auto record=sourceFileIdentity(absolute,b);Json expected=f;expected.erase("path");need(record==expected&&fileRecords.emplace(name,f).second,"evidence identity/duplicate mismatch");total+=b.size();need(total<=128*1024*1024,"total evidence bytes");fileBytes[name]=b;out.additionalPaths.push_back(info.absoluteFilePath());}
    need(fileBytes.count("contacts.json")&&parse(fileBytes.at("contacts.json"))==out.report,"frozen contacts differ");std::map<std::string,Json> links,nodes,bodies;for(const auto& b:conversion.at("assembly_audit").at("bindings"))links[b.at("part_id")]=b;for(const auto& n:conversion.at("assembly_audit").at("tree").at("nodes"))nodes[n.at("id")]=n;need(a.at("bodies").is_array()&&a.at("bodies").size()==out.parts.size(),"body count");
    for(const auto& b:a.at("bodies")){fields(b,{"part_id","occurrence_id","definition_id","root_solid_index","world_matrix","shape","profile"});auto id=b.at("part_id").get<std::string>();need(links.count(id)&&bodies.emplace(id,b).second,"body id mismatch/duplicate");const auto& link=links.at(id);const auto& node=nodes.at(link.at("occurrence_id"));need(b.at("occurrence_id")==link.at("occurrence_id")&&b.at("definition_id")==link.at("definition_id")&&b.at("root_solid_index")==node.at("root_solid_index")&&b.at("world_matrix")==node.at("world_matrix"),"body placement/binding mismatch");auto path=b.at("shape").at("path").get<std::string>();need(fileRecords.count(path)&&fileRecords.at(path)==b.at("shape"),"body serialized shape identity");topology(b.at("profile"),true);for(int k=0;k<6;++k)need(std::abs(b.at("profile").at("bounds_xyzxyz_mm")[k].get<double>()-node.at("world_bounds_xyzxyz_mm")[k].get<double>())<=1e-7,"body world bounds mismatch");}
    const auto& base=out.report.at("relations").at("pairs");need(a.at("pairs").is_array()&&a.at("pairs").size()==base.size(),"pair count");Json counts=Json::object();std::size_t jobs=0;bool complete=true;
    for(std::size_t i=0;i<base.size();++i){const auto& row=a.at("pairs")[i];fields(row,{"pair_index","part_ids","bbox_gap_mm","linear_resolution_mm","volume_resolution_mm3","classification","job"});need(count(row.at("pair_index"),495)==i&&row.at("part_ids")==base[i].at("part_ids"),"pair identity/order");const auto& aa=bodies.at(row.at("part_ids")[0].get<std::string>());const auto& bb=bodies.at(row.at("part_ids")[1].get<std::string>());const auto& x=aa.at("profile");const auto& y=bb.at("profile");need(num(row.at("bbox_gap_mm"),1e9,true)==gap(x,y)&&num(row.at("linear_resolution_mm"),1e10,true)==margin(x,y)&&num(row.at("volume_resolution_mm3"),1e30,true)==std::max(1e-12,margin(x,y)*std::max(x.at("surface_area_mm2").get<double>(),y.at("surface_area_mm2").get<double>())),"gap/resolution mismatch");std::string classification;
        if(!qualified(x)||!qualified(y)){classification="unqualified_brep";need(row.at("job").is_null(),"unexpected unqualified job");}
        else if(gap(x,y)>margin(x,y)){classification="numerical_aabb_separation_observed";need(row.at("job").is_null(),"unexpected broad-phase job");}
        else if(jobs>=64){classification="unresolved_pair_job_budget";need(row.at("job").is_null(),"job over budget");}
        else{++jobs;auto jobName="jobs/pair-"+std::to_string(i)+".json";need(fileBytes.count(jobName),"pair job evidence missing");Json expected={{"schema","scdat.brep-pair-job/1"},{"policy","scdat.brep-whole-pair-numerical/1"},{"pair_index",i},{"part_ids",row.at("part_ids")},{"inputs",Json::array({aa,bb})}};need(parse(fileBytes.at(jobName))==expected,"pair job inputs differ");const auto& j=row.at("job");need(j.is_object()&&j.contains("job_status"),"job status required");
            if(j.at("job_status")=="timeout"){fields(j,{"job_status","timeout_seconds"});need(j.at("timeout_seconds")==60,"timeout policy");classification="unresolved_job_failure";}
            else if(j.at("job_status")=="process_failed"){fields(j,{"job_status","exit_code"});num(j.at("exit_code"),1e12);need(j.at("exit_code").is_number_integer(),"process exit integer");classification="unresolved_job_failure";}
            else{fields(j,{"job_status","distances","runs","inputs_unchanged","classification","schema","policy","pair_index","part_ids","source_inputs"});need((j.at("job_status")=="completed"||j.at("job_status")=="unexpected_actual_fuzzy")&&j.at("schema")=="scdat.brep-pair-result/1"&&j.at("policy")=="scdat.brep-whole-pair-numerical/1"&&j.at("pair_index")==i&&j.at("part_ids")==row.at("part_ids")&&j.at("source_inputs")==Json::array({aa,bb}),"job result identity");auto resultName="results/pair-"+std::to_string(i)+".json";need(fileBytes.count(resultName)&&parse(fileBytes.at(resultName))==j,"frozen pair result differs");flag(j.at("inputs_unchanged"));need(j.at("distances").is_array()&&j.at("distances").size()==2,"distance order count");for(int k=0;k<2;++k){const auto& d=j.at("distances")[k];fields(d,{"order","solid_distance_mm","boundary_distance_mm","inner_solution"});need(d.at("order")==(k==0?"AB":"BA"),"distance order");num(d.at("solid_distance_mm"),1e10,true);num(d.at("boundary_distance_mm"),1e10,true);flag(d.at("inner_solution"));}need(j.at("runs").is_array()&&j.at("runs").size()==4,"run count");for(int k=0;k<4;++k){const auto& run=j.at("runs")[k];fields(run,{"order","requested_fuzzy_mm","actual_fuzzy_mm","operation_ok","has_errors","has_warnings","errors","warnings","common","inputs_unchanged"});need(run.at("order")==(k%2==0?"AB":"BA")&&run.at("requested_fuzzy_mm")==((k<2)?0.:1e-6),"run sequence");if(!run.at("actual_fuzzy_mm").is_null())num(run.at("actual_fuzzy_mm"),1e9,true);for(const char* f:{"operation_ok","has_errors","has_warnings","inputs_unchanged"})flag(run.at(f));text(run.at("errors"));text(run.at("warnings"));need(run.at("has_errors")==true||run.at("errors")=="","unflagged error diagnostics");need(run.at("has_warnings")==true||run.at("warnings")=="","unflagged warning diagnostics");if(run.at("operation_ok")==true){need(run.at("has_errors")==false&&!run.at("common").is_null(),"successful run errors/common");topology(run.at("common"),false);}else need(run.at("common").is_null(),"failed operation cannot claim common");if(j.at("job_status")=="completed")need(run.at("actual_fuzzy_mm")==((k<2)?1e-7:1e-6),"actual fuzzy mismatch");}classification=assess(j,x,y);need(j.at("classification")==classification,"job assessment differs");}
        }
        need(row.at("classification")==classification,"pair assessment differs");counts[classification]=counts.contains(classification)?counts.at(classification).get<int>()+1:1;if(classification.rfind("unresolved_",0)==0||classification=="unqualified_brep")complete=false;
    }
    need(a.at("pair_job_count")==jobs&&a.at("classification_counts")==counts&&a.at("numerical_scan_complete")==complete,"totals/completion mismatch");a.erase("contact_review");out.report["schema"]="scdat.step-brep-pair-review/1";out.report["brep_pairs"]={{"receipt",sourceFileIdentity(receiptPath,raw)},{"backend_execution_authenticated",false},{"numeric_record_checked_only",true},{"diagnostics",a}};out.report["whole_pair_geometry_certified"]=false;out.report["scope"]="Whole placed BRep pair numerical record only; reader does not re-execute CAD kernel; candidate/empty Common does not clear original mesh contact gate or authorize transport";return out;
}
